                Debug.LogWarning("没有可用的卡牌！");
                return null;
            }

            return available[Random.Range(0, available.Count)];
        }

        /// <summary>
        /// 重置已选卡牌记录（比如开始新一局游戏时调用）
        /// </summary>
        public void ResetEXCardSelection()
        {
            selectedEXCardNames.Clear();
        }
    }
}
